"""Read-only analysis of an explicitly supplied x86 StudioRender DLL; never execute it.

Install pefile==2024.8.26 capstone==5.0.6. Annotations are emitted only for the
complete SHA-256 of the user-supplied, audited sample. No signature scanning.
"""
import argparse
import hashlib
import json
from pathlib import Path
import struct

import capstone
import pefile

KNOWN = '03964dedcf8b7f4ebde24cd3d0738873d37c075a7a9b313dad001bb937f9d1b6'
RANGES = {'load_model': (0x69cd0, 0x69e84),
          'static_meshes': (0x69b00, 0x69cd0),
          'single_mesh': (0x69950, 0x69b00),
          'mesh_group': (0x69560, 0x69950),
          'vertex_helper': (0x68890, 0x68e60)}
EDGES = ((0x69e36, 0x69b00), (0x69c62, 0x69950),
         (0x69a32, 0x69560), (0x696f2, 0x68890))


def inspect(path):
    raw = path.read_bytes()
    pe = pefile.PE(data=raw)
    base = pe.OPTIONAL_HEADER.ImageBase
    report = {'sha256': hashlib.sha256(raw).hexdigest(), 'bytes': len(raw),
              'machine': hex(pe.FILE_HEADER.Machine), 'image_base': hex(base),
              'image_size': hex(pe.OPTIONAL_HEADER.SizeOfImage),
              'timestamp': hex(pe.FILE_HEADER.TimeDateStamp), 'executed': False}
    report['known_sample'] = report['sha256'] == KNOWN
    if not report['known_sample']:
        return report
    if pe.FILE_HEADER.Machine != 0x14c:
        raise ValueError('Known sample must be x86')
    disassembler = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_32)
    instructions = {}
    report['disassembly'] = {}
    for label, (start, end) in RANGES.items():
        decoded = list(disassembler.disasm(pe.get_data(start, end-start), base+start))
        if not decoded or decoded[0].address != base+start:
            raise ValueError(f'Entry could not be decoded: {label}')
        report['disassembly'][label] = [
            {'rva': hex(i.address-base), 'bytes': i.bytes.hex(),
             'instruction': f'{i.mnemonic} {i.op_str}'.strip()} for i in decoded]
        instructions.update({i.address-base: i for i in decoded})
    for site, target in EDGES:
        instruction = instructions[site]
        if instruction.mnemonic != 'call' or instruction.op_str != hex(base+target):
            raise ValueError(f'Call chain verification failed at {site:x}')
    fault = instructions[0x6896f]
    if fault.bytes != bytes.fromhex('f30f1030'):
        raise ValueError('Fault instruction mismatch')
    if pe.get_data(0x69d15, 3) != bytes.fromhex('c20c00') or pe.get_data(0x69e81, 3) != bytes.fromhex('c20c00'):
        raise ValueError('LoadModel stack cleanup mismatch')
    if struct.unpack('<I', pe.get_data(0x7f064, 4))[0] != base+0x69cd0:
        raise ValueError('Vtable entry mismatch')
    if b'.?AVCStudioRenderContext@@\0' not in pe.get_data(0x8b518, 64):
        raise ValueError('RTTI type mismatch')
    if pe.get_data(0x69cfb, 3) != bytes.fromhex('83c10c'):
        raise ValueError('Model-name offset mismatch')
    report['verified_annotations'] = {
        'fault': '0x6896f: movss xmm6, dword ptr [eax] (read)',
        'call_chain': [[hex(site), hex(target)] for site, target in EDGES],
        'entry': '0x69cd0; ECX=this; [ESP+4]=studiohdr*, [ESP+8]=vtx*, [ESP+12]=hardware*; AL=bool; ret 0x0c',
        'vtable': 'CStudioRenderContext vtable RVA 0x7f03c; slot 10 at 0x7f064',
        'name': 'studiohdr+0x0c used by actual error formatter; copy capacity 64 from SDK studiohdr',
        'lod': 'LoadModel loops over LODs; current LOD unavailable in the chosen entry Hook',
        'coverage': 'Virtual calls through this audited slot after installation; not arbitrary engine versions',
        'symbols': 'No matching PDB available; internal mesh names are structural identifications, not recovered symbols',
    }
    return report


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('dll', type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--require-known', action='store_true')
    args = parser.parse_args()
    result = inspect(args.dll)
    text = json.dumps(result, ensure_ascii=False, indent=2)+'\n'
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(text, encoding='utf-8')
        print(json.dumps({k: v for k, v in result.items() if k != 'disassembly'}, ensure_ascii=False))
    else:
        print(text)
    if args.require_known and not result['known_sample']:
        raise SystemExit('Unsupported sample; no offsets or ABI inferred')
